  const localePath = lang => lang === 'en' ? `/en${basePath === '/' ? '/' : basePath}` : basePath;
  const ui = { pt: { openMenu:'Abrir menu',closeMenu:'Fechar menu',required:'Campo obrigatório.',invalid:'Verifique este campo.',invalidPhone:'Introduza um número de telefone válido.',fixFields:'Corrija os campos assinalados.',noEndpoint:'O formulário ainda não está ligado ao sistema de candidaturas. Contacte-nos por telefone ou email.',sending:'A enviar…',submit:'Enviar candidatura',success:'Pedido enviado. A equipa entrará em contacto consigo.',network:'Não foi possível enviar. Tente novamente ou contacte-nos diretamente.' }, en: { openMenu:'Open menu',closeMenu:'Close menu',required:'Required field.',invalid:'Check this field.',invalidPhone:'Enter a valid phone number.',fixFields:'Check the highlighted fields.',noEndpoint:'The form is not connected to the application system yet. Please contact us by phone or email.',sending:'Sending…',submit:'Submit application',success:'Request sent. Our team will contact you.',network:'We could not send your request. Please try again or contact us directly.' } }[locale];
  if(!document.querySelector('[data-lang]')){const switcher=document.createElement('nav');switcher.className='page-language';switcher.setAttribute('aria-label',locale==='en'?'Language':'Idioma');switcher.innerHTML='<a data-lang="pt" lang="pt">PT</a><span>|</span><a data-lang="en" lang="en">EN</a>';document.body.prepend(switcher)}
  function applyLocaleNavigation(){
    document.documentElement.lang=isEnglish?'en':'pt-PT';
    $$('[data-lang]').forEach(link=>{const lang=link.dataset.lang;link.href=localePath(lang);link.toggleAttribute('aria-current',lang===locale);link.addEventListener('click',()=>localStorage.setItem('urbango_language',lang))});
  }
