  const setMenu=open=>{if(!menu||!menuButton)return;menuButton.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-hidden',String(!open));menu.classList.toggle('open',open);backdrop.hidden=!open;requestAnimationFrame(()=>backdrop.classList.toggle('open',open));document.body.classList.toggle('menu-open',open);if(open){previousFocus=document.activeElement;setTimeout(()=>closeButton?.focus(),250)}else if(previousFocus)menuButton.focus()};
  menuButton?.addEventListener('click',()=>setMenu(true));closeButton?.addEventListener('click',()=>setMenu(false));backdrop?.addEventListener('click',()=>setMenu(false));menu?.addEventListener('click',e=>{if(e.target.closest('a'))setMenu(false)});document.addEventListener('keydown',e=>{if(menu?.getAttribute('aria-hidden')==='true')return;if(e.key==='Escape'){setMenu(false);return}if(e.key==='Tab'){const items=focusable(),first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});addEventListener('resize',()=>{if(innerWidth>1100&&menu?.classList.contains('open'))setMenu(false)});
  const onScroll=()=>header?.classList.toggle('scrolled',scrollY>12);onScroll();addEventListener('scroll',onScroll,{passive:true});window.dataLayer=window.dataLayer||[];const track=(event,data={})=>window.dataLayer.push({event,...data});document.addEventListener('click',e=>{const item=e.target.closest('[data-event]');if(item)track(item.dataset.event,{link_url:item.href||''})});
  const phoneInput=$('#phone');const iti=phoneInput&&window.intlTelInput?window.intlTelInput(phoneInput,{initialCountry:'pt',separateDialCode:true,nationalMode:false}):null;const form=$('[data-lead-form]');
  if(form){let started=false,submitting=false;form.addEventListener('input',()=>{if(!started){started=true;track('form_start')}},{once:true});form.addEventListener('submit',async e=>{e.preventDefault();if(submitting)return;const status=$('.form-status',form);$$('.field-error',form).forEach(x=>x.textContent='');phoneInput?.removeAttribute('aria-invalid');let valid=form.checkValidity();if(iti&&phoneInput.value.trim()&&!iti.isValidNumber()){valid=false;phoneInput.setAttribute('aria-invalid','true');$('#phone-error').textContent=ui.invalidPhone}if(!valid){$$(':invalid',form).forEach(field=>{const err=field.closest('label')?.querySelector('.field-error');if(err&&!err.textContent)err.textContent=field.validity.valueMissing?ui.required:ui.invalid});(form.querySelector('[aria-invalid="true"]')||form.querySelector(':invalid'))?.focus();status.textContent=ui.fixFields;track('form_error',{reason:'validation'});return}const endpoint=form.dataset.endpoint;if(!endpoint){status.textContent=ui.noEndpoint;track('form_error',{reason:'endpoint_not_configured'});return}submitting=true;const button=$('button[type=submit]',form);button.disabled=true;button.textContent=ui.sending;track('form_submit');const payload=Object.fromEntries(new FormData(form));if(iti)payload.phone=iti.getNumber();try{const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!response.ok)throw new Error();form.reset();status.textContent=ui.success;track('form_success')}catch{status.textContent=ui.network;track('form_error',{reason:'network'})}finally{submitting=false;button.disabled=false;button.innerHTML=`${ui.submit} <span aria-hidden="true">→</span>`}})}
